contracts/Donations.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;


import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract Donations is Ownable, Pausable, ReentrancyGuard {

    enum CampaignState { Active, Successful, Failed }

    error ZeroAmount();
    error CampaignNotActive();
    error CampaignNotFinished();
    error NotRefundable();
    error NothingToWithdraw();

    string public name; // Name of the donation campaign
    string public orgName; // Name of the organization of the campaign
    string public description; // Description of the donation campaign
    uint256 public goal; // Goal(monetary) of the campaign
    uint256 public totalRaised;
    uint256 public deadline; // Deadline of the campaign
    CampaignState public state;

    mapping(address => uint256) public contributions; // donor and their totaled contributions

    event Donated(address indexed donor, uint256 amount);
    event Refunded(address indexed donor, uint256 amount);
    event Withdrawn(address indexed to, uint256 amount);
    event StateChanged(CampaignState indexed previous, CampaignState indexed current);
    event DeadlineExtended(uint256 newDeadline);

    constructor(
        string memory _name,
        string memory _orgName,
        string memory _description,
        uint256 _goal,
        uint16 _durationDays,
        address initialOwner
    ) Ownable(initialOwner) {
        if (_goal ==0) revert ZeroAmount();
        name = _name;
        orgName = _orgName;
        description = _description;
        goal = _goal;
        deadline = block.timestamp + (_durationDays * 1 days);
        state = CampaignState.Active;
    }

    function getCampaignStatus() public view returns (CampaignState) {
        if(state != CampaignState.Active) return state;
        if(block.timestamp >=deadline) {
            return (totalRaised >= goal) ? CampaignState.Successful : CampaignState.Failed;
        }
        if(totalRaised >= goal) {
            return CampaignState.Successful;
        }

        return CampaignState.Active;
    }

    function getBalance() external view returns (uint256) {
        return address(this).balance;
    }

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    function extendDeadline(uint256 daysToAdd) external onlyOwner {
        _recomputeAndSetState();
        if (getCampaignStatus() != CampaignState.Active || block.timestamp >= deadline) {
            revert CampaignNotActive();
        }
        deadline += daysToAdd * 1 days;
        emit DeadlineExtended(deadline);
    }

    function donate() external payable whenNotPaused nonReentrant {
        _recomputeAndSetState();
        if (getCampaignStatus() != CampaignState.Active) revert CampaignNotActive();
        if (msg.value == 0) revert ZeroAmount();

        // Effects
        contributions[msg.sender] += msg.value;
        totalRaised += msg.value;

        emit Donated(msg.sender, msg.value);

        _recomputeAndSetState();
    }

    function withdraw(address payable to) external onlyOwner nonReentrant {
        _recomputeAndSetState();
        if (getCampaignStatus() != CampaignState.Successful) revert CampaignNotFinished();

        uint256 amount = address(this).balance;
        if (amount == 0) revert NothingToWithdraw();

        (bool ok, ) = to.call{value: amount}("");
        require(ok, "ETH send failed");
        emit Withdrawn(to, amount);
    }

    function refund() external nonReentrant {
        _recomputeAndSetState();
        if (getCampaignStatus() != CampaignState.Failed) revert NotRefundable();

        uint256 amount = contributions[msg.sender];
        if (amount == 0) revert NotRefundable();

        contributions[msg.sender] = 0;

        (bool ok, ) = payable(msg.sender).call{value: amount}("");
        require(ok, "ETH send failed");
        emit Refunded(msg.sender, amount);
    }

    function _recomputeAndSetState() internal {
        CampaignState current = state;
        CampaignState next = getCampaignStatus();
        if (next != current) {
            state = next;
            emit StateChanged(current, next);
        }
    }

    receive() external payable {
        revert("Use donate()");
    }
    fallback() external payable {
        revert("Use donate()");
    }
}

contracts/DonationsFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "./Donations.sol";

/**
 * @title DonationsFactory
 * @notice Deploys and indexes Donations campaigns.
 * - Tracks all deployed campaign addresses
 * - Tracks campaigns per owner (the owner is set to msg.sender on creation)
 */
contract DonationsFactory {
    /// @dev All campaigns ever created by this factory
    address[] private _allCampaigns;

    /// @dev Owner (creator) => list of their campaigns
    mapping(address => address[]) private _ownerCampaigns;

    /// @dev Quick membership check
    mapping(address => bool) public isRegisteredCampaign;

    event CampaignCreated(
        address indexed owner,
        address campaign,
        string name,
        string orgName,
        string description,
        uint256 goal,
        uint16 durationDays,
        uint256 expectedDeadline
    );

    /**
     * @notice Create a new Donations campaign owned by msg.sender.
     * @param _name         Human-readable campaign name
     * @param _orgName      Organization name
     * @param _description  Campaign description
     * @param _goal         Fundraising goal (wei)
     * @param _durationDays Campaign duration in days
     * @return campaign     Address of the deployed Donations contract
     */
    function createCampaign(
        string memory _name,
        string memory _orgName,
        string memory _description,
        uint256 _goal,
        uint16 _durationDays
    ) external returns (address campaign) {
        Donations d = new Donations(
            _name,
            _orgName,
            _description,
            _goal,
            _durationDays,
            msg.sender // initialOwner
        );

        campaign = address(d);
        _registerCampaign(msg.sender, campaign);

        uint256 expectedDeadline = block.timestamp + (uint256(_durationDays) * 1 days);

        emit CampaignCreated(
            msg.sender,
            campaign,
            _name,
            _orgName,
            _description,
            _goal,
            _durationDays,
            expectedDeadline
        );
    }

    // ----------------------------- Views -----------------------------

    function getAllCampaigns() external view returns (address[] memory) {
        return _allCampaigns;
    }

    function getOwnerCampaigns(address owner) external view returns (address[] memory) {
        return _ownerCampaigns[owner];
    }

    function campaignsCount() external view returns (uint256) {
        return _allCampaigns.length;
    }

    function ownerCampaignsCount(address owner) external view returns (uint256) {
        return _ownerCampaigns[owner].length;
    }

    // --------------------------- Internal ----------------------------

    function _registerCampaign(address owner, address campaign) internal {
        _allCampaigns.push(campaign);
        _ownerCampaigns[owner].push(campaign);
        isRegisteredCampaign[campaign] = true;
    }
}

contracts/Lock.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

// Uncomment this line to use console.log
// import "hardhat/console.sol";

contract Lock {
    uint public unlockTime;
    address payable public owner;

    event Withdrawal(uint amount, uint when);

    constructor(uint _unlockTime) payable {
        require(
            block.timestamp < _unlockTime,
            "Unlock time should be in the future"
        );

        unlockTime = _unlockTime;
        owner = payable(msg.sender);
    }

    function withdraw() public {
        // Uncomment this line, and the import of "hardhat/console.sol", to print a log in your terminal
        // console.log("Unlock time is %o and block timestamp is %o", unlockTime, block.timestamp);

        require(block.timestamp >= unlockTime, "You can't withdraw yet");
        require(msg.sender == owner, "You aren't the owner");

        emit Withdrawal(address(this).balance, block.timestamp);

        owner.transfer(address(this).balance);
    }
}

